mapper.sql:
WHERE ics40_company_id = #{companyId}
  AND ics40_reg_date BETWEEN #{startDate} AND #{closeDate}
  AND ics40_dcr_type_cd LIKE #{dcrTypeCode}
  AND CONCAT((CASE WHEN ics40_appr_no_prefix IS NULL
                   THEN ''
                   ELSE ics40_appr_no_prefix || LPAD(ics40_appr_no_seq::TEXT, 3, '0') END),
             ics40_provide_co, ics40_content, f_emp_kor_nm(ics40_person_id), ics40_dcr_type_cd) ILIKE #{searchText}
  AND COALESCE(ics40_status_cd, '') IN ('10', '20', '80')
ORDER BY ics40_dcr_preconfirm_id DESC

mapper.select:
SELECT COUNT(*)
  FROM ics40_dcr_preconfirm
 WHERE ics40_company_id  = #{companyId}
   AND ics40_pre_appr_no = #{apprNo}

mapper.update:
UPDATE ics40_dcr_preconfirm
   SET ics40_confirm_msg = #{confirmMsg}
 WHERE ics40_company_id = #{companyId}
   AND ics40_dcr_preconfirm_id = #{dcrPreconfirmId}

mapper.select:
SELECT COALESCE(sys01_dcr_preconfirm_skip_yn, 'false') = 'true'
  FROM sys01_company
 WHERE sys01_company_id = #{companyId}

mapper.delete:
DELETE FROM sys99_print
 WHERE sys99_company_id      = #{companyId}
   AND sys99_person_id       = #{personId}
   AND sys99_window_class_nm LIKE #{windowClassName}

mapper.insert:
INSERT INTO sys99_print
       ( sys99_print_id, sys99_company_id, sys99_person_id, sys99_window_class_nm, sys99_group_id
       , sys99_date01, sys99_string01, sys99_string02, sys99_string03, sys99_text01
       , sys99_string04, sys99_string05, sys99_date02, sys99_string06, sys99_text02
       , sys99_text03, sys99_string07, sys99_string08, sys99_string09, sys99_string10
       , sys99_date03, sys99_date04, sys99_string11, sys99_string12, sys99_string13
       , sys99_long01 )
VALUES ( #{printId}, #{companyId}, #{personId}, #{windowClassName}, #{groupId}
       , #{row.regDate}, #{row.dcrTypeName}, #{row.apprNoPrefix}, #{row.provideCo}, #{row.content}
       , #{row.personName}, #{row.confirmerName}, #{row.confirmDate}, #{row.statusName}, #{row.confirmMsg}
       , #{row.regEmpMsg}, #{row.adTypeName}, #{row.mediaTypeName}, #{row.adItemName}, #{row.adContent}
       , #{row.startDate}, #{row.closeDate}, #{row.spec}, #{row.qtyCnt}, #{row.preApprNo}
       , #{row.dcrPreconfirmId} )

mapper.select:

WHERE ics41_company_id = #{companyId}
  AND CONCAT(ics41_dcr_type_cd, ics41_dcr_type_nm) ILIKE #{searchText}
  AND COALESCE(ics41_use_yn, 'false') LIKE #{useYn}


WHERE ics41_company_id = #{companyId}
  AND UPPER(ics41_dcr_type_cd) = UPPER(#{dcrTypeCode})
  AND ics41_use_yn = 'true'

mapper.delete:
DELETE FROM ics41_dcr_type
 WHERE ics41_dcr_type_id = #{dcrTypeId}
   AND ics41_company_id  = #{companyId}
